insert into public.formula_cards (
  id, chapter_id, title, card_type, body, formulas, variables, conditions, table_data, diagram_data, diagram_svg, recall_data, importance, source_page, sort_order, is_active
)
values
  ('neet-biology-neural-control-and-co-ordination-neural-system-overview', 'neet-biology-neural-control-and-co-ordination', 'Neural System Overview', 'concept', 'The neural system controls and coordinates body activities, conducts and integrates information and responds to stimuli.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Recall cue","Source-backed answer"],"rows":[["Includes","Brain, spinal cord and nerves"],["Made of","Specialized cells known as neurons"],["Neuron","Structural and functional unit of neural system"]]}'::jsonb, null, null, '{"recall_question":"What is the structural and functional unit of the neural system?","reveal_answer":"Neuron.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 82, 1, true),
  ('neet-biology-neural-control-and-co-ordination-neuron-structure', 'neet-biology-neural-control-and-co-ordination', 'Neuron Structure', 'classification', 'A neuron has a cell body, dendron with dendrites and an axon.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Part","Source-backed recall"],"rows":[["Cell body or cyton","Contains cytoplasm, cell organelles and Nissl''s granules"],["Dendron","Short fibres projecting from the cyton"],["Dendrites","Sub-branches that transmit impulses towards the cyton"],["Axon","Long fibre transmitting impulses away from the cell body"],["Axonite","Branching of axon"],["Synaptic knob","Bulb-like end of each axonite"]]}'::jsonb, '{"type":"bio-neuron-structure"}'::jsonb, null, '{"recall_question":"Which neuron process carries impulses away from the cell body?","reveal_answer":"Axon.","key_points":[],"examples":[],"neet_traps":["Dendrites transmit impulses towards the cyton."]}'::jsonb, 5, 82, 2, true),
  ('neet-biology-neural-control-and-co-ordination-types-of-neurons', 'neet-biology-neural-control-and-co-ordination', 'Types of Neurons', 'classification', 'The source classifies neurons by axon and dendron count.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Type","Structure","Source location"],"rows":[["Unipolar","One axon and no dendron","Embryo"],["Bipolar","One axon and one dendron","Retina"],["Multipolar","One axon and 2 or more dendrons","Most common; CNS and PNS"]]}'::jsonb, null, null, '{"recall_question":"Which neuron type is most common?","reveal_answer":"Multipolar neuron.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 4, 82, 3, true),
  ('neet-biology-neural-control-and-co-ordination-myelinated-vs-non-myelinated', 'neet-biology-neural-control-and-co-ordination', 'Myelinated vs Non-Myelinated Axon', 'comparison', 'Schwann cells are present in both types, but only myelinated axons have a myelin sheath.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Feature","Myelinated axon","Non-myelinated axon"],"rows":[["Schwann cells","Envelope the axon and form myelin sheath","Present but no myelin sheath"],["Matter colour","White matter is formed of myelinated nerve fibres","Gray matter is without myelin sheath"],["Nodes","Gaps between adjacent myelin sheaths are nodes of Ranvier","No myelin sheath gaps"],["Source location","Spinal and cranial nerves","Autonomous and somatic neural systems"]]}'::jsonb, null, null, '{"recall_question":"What are nodes of Ranvier?","reveal_answer":"Gaps between two adjacent myelin sheaths.","key_points":[],"examples":[],"neet_traps":["Non-myelinated axons still have Schwann cells, but no myelin sheath."]}'::jsonb, 5, 82, 4, true),
  ('neet-biology-neural-control-and-co-ordination-resting-membrane-potential', 'neet-biology-neural-control-and-co-ordination', 'Resting Membrane Potential', 'concept', 'In a resting neuron, the axonal membrane is polarized.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Cue","Source-backed detail"],"rows":[["Membrane permeability","More permeable to K+ and nearly impermeable to Na+"],["Inside axoplasm","High K+ and negatively charged proteins; low Na+"],["Outside axon","Low K+ and high Na+"],["Na-K pump","Transports 3 Na+ outwards for 2 K+ into the cell"],["Polarity","Outer surface positive and inner surface negative"],["Resting potential","Electrical potential difference across resting plasma membrane"]]}'::jsonb, '{"type":"bio-action-potential-flow"}'::jsonb, null, '{"recall_question":"What does the Na-K pump do in the source?","reveal_answer":"It transports 3 Na+ outwards for 2 K+ into the cell.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 82, 5, true),
  ('neet-biology-neural-control-and-co-ordination-action-potential', 'neet-biology-neural-control-and-co-ordination', 'Action Potential', 'process', 'A stimulus makes the membrane permeable to Na+, causing depolarization and nerve impulse generation.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Step","Source-backed event"],"rows":[["1","Stimulus is applied at site A"],["2","Membrane becomes permeable to Na+"],["3","Rapid influx of Na+ reverses polarity"],["4","Outer surface becomes negative and inner surface becomes positive"],["5","This depolarization produces action potential or nerve impulse"]]}'::jsonb, null, null, '{"recall_question":"What ion rapidly enters during depolarization?","reveal_answer":"Na+.","key_points":["The source calls the electrical potential difference during depolarization action potential."],"examples":[],"neet_traps":[]}'::jsonb, 5, 82, 6, true),
  ('neet-biology-neural-control-and-co-ordination-propagation-and-repolarization', 'neet-biology-neural-control-and-co-ordination', 'Propagation and Repolarization', 'sequence', 'Action potential at one site generates action potential at the next site, then K+ movement restores the resting membrane.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Phase","Source-backed recall"],"rows":[["Propagation","Current flows from site A to site B on inner surface and from site B to site A on outer surface"],["Next action potential","Polarity is reversed and action potential is generated at site B"],["Na+ permeability","Rise is extremely short lived"],["K+ permeability","Quickly rises after Na+ permeability"],["Restoration","K+ diffuses outside and restores the resting membrane"]]}'::jsonb, null, null, '{"recall_question":"Which ion diffuses out to restore the resting membrane?","reveal_answer":"K+.","key_points":[],"examples":[],"neet_traps":["The source does not include saltatory conduction here."]}'::jsonb, 5, 82, 7, true),
  ('neet-biology-neural-control-and-co-ordination-electrical-vs-chemical-synapse', 'neet-biology-neural-control-and-co-ordination', 'Electrical vs Chemical Synapse', 'comparison', 'Synapse is a functional junction between two neurons.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Feature","Electrical synapse","Chemical synapse"],"rows":[["Membrane relation","Pre- and post-synaptic membranes are in close proximity","Fluid-filled synaptic cleft between neurons"],["Transmission","Similar to transmission along an axon","Uses neurotransmitters"],["Speed","Faster than chemical synapse","Slower than electrical synapse"],["Human system","Very rare","Commonly described with synaptic vesicles and receptors"]]}'::jsonb, null, null, '{"recall_question":"Which synapse is very rare in the human system?","reveal_answer":"Electrical synapse.","key_points":[],"examples":[],"neet_traps":["Chemical synapses have a synaptic cleft."]}'::jsonb, 5, 82, 8, true),
  ('neet-biology-neural-control-and-co-ordination-chemical-synapse-transmission', 'neet-biology-neural-control-and-co-ordination', 'Chemical Synapse Transmission', 'sequence', 'The source gives chemical synapse transmission as a receptor-mediated flow.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Step","Event"],"rows":[["1","Impulse reaches axon terminal"],["2","Synaptic vesicles bind on plasma membrane"],["3","Neurotransmitter is released"],["4","Neurotransmitter diffuses across synaptic cleft"],["5","It combines with receptors on post-synaptic membrane"],["6","Ion channels open, ions enter and action potential is generated"]]}'::jsonb, '{"type":"bio-synapse-flow"}'::jsonb, null, '{"recall_question":"Name two neurotransmitters listed in the source.","reveal_answer":"Acetylcholine and adrenaline.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 83, 9, true),
  ('neet-biology-neural-control-and-co-ordination-cns-vs-pns', 'neet-biology-neural-control-and-co-ordination', 'CNS vs PNS', 'comparison', 'The human nervous system has central and peripheral parts.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["System","Source-backed components"],"rows":[["Central neural system (CNS)","Brain and spinal cord"],["Peripheral nervous system (PNS)","All nerves; includes cranial nerves and spinal nerves"]]}'::jsonb, null, null, '{"recall_question":"What are the two parts of CNS?","reveal_answer":"Brain and spinal cord.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 83, 10, true),
  ('neet-biology-neural-control-and-co-ordination-brain-classification', 'neet-biology-neural-control-and-co-ordination', 'Brain Classification', 'classification', 'Brain has three divisions: forebrain, midbrain and hindbrain.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Division","Source-backed parts"],"rows":[["Forebrain","Cerebrum and diencephalon"],["Midbrain","Corpora quadrigemina and cerebral aqueduct region"],["Hindbrain","Cerebellum, pons and medulla oblongata"],["Brain stem","Midbrain and hindbrain"]]}'::jsonb, '{"type":"bio-brain-classification"}'::jsonb, null, '{"recall_question":"Which brain divisions form the brain stem?","reveal_answer":"Midbrain and hindbrain.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 83, 11, true),
  ('neet-biology-neural-control-and-co-ordination-brain-protection', 'neet-biology-neural-control-and-co-ordination', 'Brain Protection', 'fact', 'The brain is protected in the cranial cavity and covered by cranial meninges.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Structure","Source-backed recall"],"rows":[["Meninges","Outer dura mater, middle arachnoid mater and inner pia mater"],["Subarachnoid space","Between pia mater and arachnoid mater; filled with cerebrospinal fluid"],["Ventricles","Also filled with CSF"]]}'::jsonb, null, null, '{"recall_question":"Which space contains cerebrospinal fluid?","reveal_answer":"Subarachnoid space.","key_points":["The ventricles of the brain are also filled with CSF."],"examples":[],"neet_traps":[]}'::jsonb, 4, 83, 12, true),
  ('neet-biology-neural-control-and-co-ordination-cerebrum-cortex', 'neet-biology-neural-control-and-co-ordination', 'Cerebrum and Cerebral Cortex', 'classification', 'The cerebrum is the largest part of the brain.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Structure","Source-backed recall"],"rows":[["Cerebral hemispheres","Two hemispheres held together by corpus callosum"],["Cerebral cortex","Outer part with convolutions and depressions; formed of gray matter"],["White matter","Inner part of cerebrum"],["Motor area","Controls voluntary movements of muscles"],["Sensory area","Controls functioning of sense organs"],["Association area","Responsible for intersensory associations, memory and communication"]]}'::jsonb, null, null, '{"recall_question":"Which tract holds the two cerebral hemispheres together?","reveal_answer":"Corpus callosum.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 83, 13, true),
  ('neet-biology-neural-control-and-co-ordination-thalamus-hypothalamus', 'neet-biology-neural-control-and-co-ordination', 'Thalamus vs Hypothalamus', 'comparison', 'Diencephalon includes thalamus and hypothalamus.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Structure","Source-backed function"],"rows":[["Thalamus","Coordinating centre or relay station for sensory and motor impulses"],["Hypothalamus","Regulates temperature, thirst, hunger and emotions"],["Hypothalamus","Secretes hypothalamic hormones and controls pituitary gland"],["Hypothalamus","Controls sleep, wakefulness, blood pressure and heart rate"]]}'::jsonb, null, null, '{"recall_question":"Which part regulates hunger and body temperature?","reveal_answer":"Hypothalamus.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 83, 14, true),
  ('neet-biology-neural-control-and-co-ordination-midbrain-hindbrain-functions', 'neet-biology-neural-control-and-co-ordination', 'Midbrain and Hindbrain Functions', 'comparison', 'The source gives compact structure-function points for midbrain and hindbrain.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Part","Function/detail"],"rows":[["Corpora quadrigemina","Anterior pair is centre of visual reflexes; posterior pair is centre of auditory reflex"],["Cerebellum","Coordinates muscular activities and body equilibrium"],["Pons varoli","Interconnects brain regions; coordinates eye and ear activities and regulates respiration"],["Medulla oblongata","Controls respiration, cardiovascular reflexes, gastric secretions, peristalsis, salivation, vomiting, sneezing and coughing"]]}'::jsonb, null, null, '{"recall_question":"Which hindbrain part coordinates muscular activities and body equilibrium?","reveal_answer":"Cerebellum.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 83, 15, true),
  ('neet-biology-neural-control-and-co-ordination-spinal-cord', 'neet-biology-neural-control-and-co-ordination', 'Spinal Cord', 'fact', 'Spinal cord is enclosed within the spinal canal and protected by meninges.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Cue","Source-backed detail"],"rows":[["Central canal","Contains CSF"],["Matter arrangement","Outer white matter and inner gray matter"],["Function 1","Conduction of impulses to and from the brain"],["Function 2","Centre of spinal reflexes"]]}'::jsonb, null, null, '{"recall_question":"What are the two functions of spinal cord in the source?","reveal_answer":"Conduction of impulses to and from the brain, and centre of spinal reflexes.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 4, 83, 16, true),
  ('neet-biology-neural-control-and-co-ordination-afferent-vs-efferent', 'neet-biology-neural-control-and-co-ordination', 'Afferent vs Efferent Fibres', 'comparison', 'PNS nerve fibres are sensory or motor by direction of impulse.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Fibre","Direction"],"rows":[["Afferent or sensory","Carry impulses from sense organs to CNS"],["Efferent or motor","Carry impulses from CNS to muscles and glands"]]}'::jsonb, null, null, '{"recall_question":"Which fibre carries impulses from sense organs to CNS?","reveal_answer":"Afferent or sensory fibre.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 84, 17, true),
  ('neet-biology-neural-control-and-co-ordination-somatic-vs-autonomic', 'neet-biology-neural-control-and-co-ordination', 'Somatic vs Autonomic Neural System', 'comparison', 'PNS has somatic and autonomic divisions.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Division","Source-backed role"],"rows":[["Somatic neural system","Relays impulses from CNS to skeletal muscles"],["Autonomic neural system","Transmits impulses from CNS to involuntary organs and smooth muscles"],["Visceral nervous system","Nerves, fibres, ganglia and plexus carrying impulses between CNS and viscera"]]}'::jsonb, null, null, '{"recall_question":"Which PNS division relays impulses to skeletal muscles?","reveal_answer":"Somatic neural system.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 84, 18, true),
  ('neet-biology-neural-control-and-co-ordination-sympathetic-vs-parasympathetic', 'neet-biology-neural-control-and-co-ordination', 'Sympathetic vs Parasympathetic', 'comparison', 'The source contrasts emergency preparation with resting-state return.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["System","Source-backed effect"],"rows":[["Sympathetic","Prepares body for emergencies, stresses and dangers"],["Sympathetic","Increases heartbeat and breathing rate, constricts arteries and elevates BP"],["Parasympathetic","Returns body to resting state after stressful situations"],["Parasympathetic","Slows heartbeat, dilates arteries and lowers BP"]]}'::jsonb, null, null, '{"recall_question":"Which autonomic division elevates BP in the source?","reveal_answer":"Sympathetic system.","key_points":[],"examples":[],"neet_traps":["Parasympathetic lowers BP."]}'::jsonb, 5, 84, 19, true),
  ('neet-biology-neural-control-and-co-ordination-reflex-action', 'neet-biology-neural-control-and-co-ordination', 'Reflex Action', 'concept', 'Reflex action is a rapid, involuntary and unconscious action of the body in response to a stimulus.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Source examples","Recall detail"],"rows":[["Hot object","Withdrawal of hand"],["Nursing baby","Touching lips evokes sucking reflex"],["Light","Closing of eyelids"],["Knee jerk","Knee jerk phenomenon"],["Conditioned reflex","Repeated seeing or smelling a food before tasting can evoke salivation"]]}'::jsonb, null, null, '{"recall_question":"What is reflex action?","reveal_answer":"Rapid, involuntary and unconscious action of body in response to a stimulus.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 84, 20, true),
  ('neet-biology-neural-control-and-co-ordination-reflex-arc', 'neet-biology-neural-control-and-co-ordination', 'Reflex Arc', 'sequence', 'Reflex arc is the pathway of impulses in a reflex action.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Order","Component"],"rows":[["1","Receptor organ receives stimulus"],["2","Sensory or afferent neuron transmits impulse to CNS"],["3","Intermediate or connector neuron connects sensory and motor neurons"],["4","Motor or efferent neuron conducts impulse to effector organ"],["5","Effector organ, muscle or gland, responds"]]}'::jsonb, '{"type":"bio-reflex-arc"}'::jsonb, null, '{"recall_question":"Which neuron connects sensory and motor neurons in a reflex arc?","reveal_answer":"Intermediate or connector neuron.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 84, 21, true),
  ('neet-biology-neural-control-and-co-ordination-eye-layers', 'neet-biology-neural-control-and-co-ordination', 'Eye Layers and Front Structures', 'classification', 'The eyeball has three layers: sclera, choroid and retina.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Structure","Source-backed recall"],"rows":[["Sclera","External layer formed of dense connective tissue"],["Cornea","Anterior transparent portion of sclera"],["Choroid","Bluish middle layer containing many blood vessels"],["Ciliary body","Thick anterior choroid forms ciliary body"],["Iris","Visible pigmented opaque portion with pupil"],["Pupil","Diameter regulated by muscle fibres of iris"],["Lens","Transparent crystalline lens held by ligaments attached to ciliary body"]]}'::jsonb, '{"type":"bio-eye-layout"}'::jsonb, null, '{"recall_question":"Which eye layer forms the cornea anteriorly?","reveal_answer":"Sclera.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 84, 22, true),
  ('neet-biology-neural-control-and-co-ordination-retina-rods-cones', 'neet-biology-neural-control-and-co-ordination', 'Rods vs Cones', 'comparison', 'Retina contains ganglion cells, bipolar cells and photoreceptor cells.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Feature","Cones","Rods"],"rows":[["Function","Daylight or photopic vision and colour vision","Twilight or scotopic vision"],["Photopigment","Photopsin responding to red, green and blue lights","Rhodopsin or visual purple"],["Vitamin link","Photopigments are formed of opsin and retinal","Rhodopsin contains a derivative of Vitamin A"],["Special location","Only cones are densely packed in fovea","-"]]}'::jsonb, null, null, '{"recall_question":"Which photoreceptors are responsible for twilight vision?","reveal_answer":"Rod cells.","key_points":[],"examples":[],"neet_traps":["Cones are for daylight and colour vision."]}'::jsonb, 5, 84, 23, true),
  ('neet-biology-neural-control-and-co-ordination-blind-spot-fovea', 'neet-biology-neural-control-and-co-ordination', 'Blind Spot and Fovea', 'fact', 'The source distinguishes the blind spot from macula lutea and fovea.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Structure","Source-backed recall"],"rows":[["Blind spot","Region where optic nerves leave eye and retinal blood vessels enter; photoreceptors absent"],["Macula lutea","Yellowish pigmented spot lateral to blind spot"],["Fovea","Central pit of macula lutea with only densely packed cones; point of greatest visual acuity"]]}'::jsonb, null, null, '{"recall_question":"Where is visual acuity greatest?","reveal_answer":"Fovea.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 84, 24, true),
  ('neet-biology-neural-control-and-co-ordination-aqueous-vs-vitreous', 'neet-biology-neural-control-and-co-ordination', 'Aqueous vs Vitreous Humour', 'comparison', 'The source names two chambers and their contents.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Chamber","Location","Content"],"rows":[["Aqueous chamber","Between cornea and lens","Aqueous humor, a thin watery fluid"],["Vitreous chamber","Between lens and retina","Vitreous humor, a transparent gel"]]}'::jsonb, null, null, '{"recall_question":"Which chamber contains a transparent gel?","reveal_answer":"Vitreous chamber.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 4, 85, 25, true),
  ('neet-biology-neural-control-and-co-ordination-vision-mechanism', 'neet-biology-neural-control-and-co-ordination', 'Mechanism of Vision', 'sequence', 'Vision begins with light focusing on retina and ends with analysis in visual cortex.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Step","Source-backed event"],"rows":[["1","Light reflected from object enters through cornea and lens"],["2","Light focuses on retina"],["3","Retinal dissociates from opsin"],["4","Membrane permeability changes and impulse forms in photoreceptors"],["5","Action potentials form in ganglion cells through bipolar cells"],["6","Optic nerves transmit impulses to brain visual cortex"],["7","Image is recognized based on memory and experience"]]}'::jsonb, null, null, '{"recall_question":"Which nerve transmits visual impulses to the brain?","reveal_answer":"Optic nerve.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 85, 26, true),
  ('neet-biology-neural-control-and-co-ordination-ear-divisions', 'neet-biology-neural-control-and-co-ordination', 'Outer vs Middle vs Inner Ear', 'comparison', 'The ear is the stato-acoustic organ for hearing and balancing.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Division","Source-backed structures/functions"],"rows":[["External ear","Pinna and auditory meatus; wax and hairs protect ears from foreign objects"],["Middle ear","Tympanic cavity and ear ossicles; Eustachian canal maintains equal pressure on either side of eardrum"],["Inner ear","Bony labyrinth and membranous labyrinth; cochlea and vestibular apparatus"]]}'::jsonb, '{"type":"bio-ear-layout"}'::jsonb, null, '{"recall_question":"Which tube connects middle ear to pharynx?","reveal_answer":"Auditory tube or Eustachian canal.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 85, 27, true),
  ('neet-biology-neural-control-and-co-ordination-ear-ossicles-cochlea', 'neet-biology-neural-control-and-co-ordination', 'Ear Ossicles and Cochlea', 'classification', 'The source gives key small-bone and cochlear membrane details.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Structure","Source-backed recall"],"rows":[["Malleus","Attached to tympanum"],["Incus","One of the three ear ossicles"],["Stapes","Smallest bone of the body; attached to oval window"],["Scala vestibula and scala media","Separated by Reissner''s membrane"],["Scala media and scala tympani","Separated by basilar membrane"],["Organ of Corti","Complex receptor organ with sensory hair cells"]]}'::jsonb, null, null, '{"recall_question":"What is the smallest bone of the body?","reveal_answer":"Stapes.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 85, 28, true),
  ('neet-biology-neural-control-and-co-ordination-hearing-mechanism', 'neet-biology-neural-control-and-co-ordination', 'Mechanism of Hearing', 'sequence', 'Sound becomes auditory nerve impulses through eardrum, ossicles, cochlear fluid and hair cells.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Step","Event"],"rows":[["1","Pinna collects sound waves"],["2","Waves reach tympanic membrane via ear canal"],["3","Tympanic membrane vibrates"],["4","Vibrations transmit to ear ossicles and oval window"],["5","Perilymph in vestibular canal vibrates"],["6","Basilar membrane vibrates and hair cells press against tectorial membrane"],["7","Auditory nerve carries impulses to auditory centre of brain"]]}'::jsonb, null, null, '{"recall_question":"Which membrane do sensory hair cell endings press against?","reveal_answer":"Tectorial membrane.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 85, 29, true),
  ('neet-biology-neural-control-and-co-ordination-vestibular-apparatus', 'neet-biology-neural-control-and-co-ordination', 'Vestibular Apparatus', 'classification', 'Vestibular apparatus is responsible for equilibrium and posture.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Part","Source-backed detail"],"rows":[["Semicircular canals","Three canals; two vertical and one horizontal"],["Ampulla","Bulging at one end of each canal"],["Crista ampullaris","Lump inside ampulla; long cilia form cupula"],["Otolith organ","Consists of utricle and saccule"],["Macula","Projecting ridge of utricle and saccule"],["Crista and Macula","Specific receptors containing sensory hair cells"]]}'::jsonb, null, null, '{"recall_question":"Which receptors are responsible for equilibrium and posture?","reveal_answer":"Crista and Macula.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 4, 85, 30, true),
  ('neet-biology-neural-control-and-co-ordination-nose-tongue-skin', 'neet-biology-neural-control-and-co-ordination', 'Nose, Tongue and Skin', 'classification', 'The source closes sense organs with smell, taste and skin receptors.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Organ","Source-backed recall"],"rows":[["Nose","Organ of smell; olfactory receptors are made of olfactory epithelium"],["Tongue","Organ of taste; four primary tastes are sweet, salt, sour and bitter"],["Nose and tongue","Chemoreceptors; taste and smell are functionally similar and interrelated"],["Skin","Largest sense organ; receptors for heat, cold, touch, pain and pressure"]]}'::jsonb, null, null, '{"recall_question":"Which sense organ is the largest?","reveal_answer":"Skin.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 4, 86, 31, true),
  ('neet-biology-chemical-co-ordination-and-integration-endocrine-system-overview', 'neet-biology-chemical-co-ordination-and-integration', 'Endocrine System Overview', 'concept', 'Endocrine system includes endocrine or ductless glands and their secretions called hormones.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Term","Source-backed meaning"],"rows":[["Endocrine glands","Ductless glands"],["Hormones","Non-nutrient chemicals acting as intercellular messengers"],["Amount","Produced in trace amounts"]]}'::jsonb, null, null, '{"recall_question":"What are hormones in the source?","reveal_answer":"Non-nutrient chemicals that act as intercellular messengers and are produced in trace amounts.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 87, 1, true),
  ('neet-biology-chemical-co-ordination-and-integration-human-endocrine-glands', 'neet-biology-chemical-co-ordination-and-integration', 'Human Endocrine Glands', 'classification', 'The source lists nine human endocrine gland groups.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Order","Gland"],"rows":[["1","Hypothalamus"],["2","Pituitary"],["3","Pineal"],["4","Thyroid"],["5","Parathyroid"],["6","Thymus"],["7","Adrenals"],["8","Pancreas or Islets of Langerhans"],["9","Gonads: testis and ovary"]]}'::jsonb, null, null, '{"recall_question":"Which endocrine gland is listed as Islets of Langerhans?","reveal_answer":"Pancreas.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 4, 87, 2, true),
  ('neet-biology-chemical-co-ordination-and-integration-hypothalamus-hormones', 'neet-biology-chemical-co-ordination-and-integration', 'Hypothalamus Hormones', 'classification', 'Neurosecretory cells of hypothalamus secrete releasing hormones, inhibiting hormones, oxytocin and vasopressin.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Hormone type","Source-backed role/example"],"rows":[["Releasing hormones","Stimulate secretion of pituitary hormones"],["GnRH","Stimulates pituitary to release gonadotropins FSH and LH"],["Inhibiting hormones","Inhibit secretion of pituitary hormones"],["Somatostatin","Inhibits release of growth hormone from pituitary"],["Oxytocin and vasopressin","Transported axonally and stored in pituitary"]]}'::jsonb, null, null, '{"recall_question":"Which hypothalamic hormone inhibits GH release in the source?","reveal_answer":"Somatostatin.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 87, 3, true),
  ('neet-biology-chemical-co-ordination-and-integration-pituitary-lobes', 'neet-biology-chemical-co-ordination-and-integration', 'Anterior vs Posterior Pituitary', 'comparison', 'Pituitary is in sella tursica and attached to hypothalamus by a stalk.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Feature","Adenohypophysis","Neurohypophysis"],"rows":[["Position/name","Anterior pituitary","Posterior pituitary"],["Parts","Pars distalis and pars intermedia","Stores oxytocin and vasopressin from hypothalamus"],["Source role","Produces pituitary hormones","Storage and release of hypothalamic hormones"]]}'::jsonb, '{"type":"bio-hypothalamus-pituitary"}'::jsonb, null, '{"recall_question":"Which pituitary part stores oxytocin and vasopressin?","reveal_answer":"Neurohypophysis.","key_points":[],"examples":[],"neet_traps":["They are from hypothalamus and transported axonally."]}'::jsonb, 5, 87, 4, true),
  ('neet-biology-chemical-co-ordination-and-integration-anterior-pituitary-hormones', 'neet-biology-chemical-co-ordination-and-integration', 'Anterior Pituitary Hormones', 'table', 'Pars distalis produces major anterior pituitary hormones.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Hormone","Source-backed function"],"rows":[["GH or somatotropin","Body growth"],["PRL or prolactin","Growth of mammary glands and milk production"],["TSH","Stimulates thyroid gland to secrete thyroid hormones"],["ACTH","Stimulates adrenal cortex to synthesise and secrete steroid hormones or glucocorticoids"],["FSH","Stimulates gonadal activity; spermatogenesis in males and ovarian follicle growth/development in females"],["LH","Stimulates gonadal activity; androgen secretion in males, ovulation and corpus luteum maintenance in females"],["MSH","From pars intermedia; acts on melanocytes to regulate skin pigmentation"]]}'::jsonb, null, null, '{"recall_question":"Which anterior pituitary hormone stimulates thyroid hormone secretion?","reveal_answer":"TSH.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 87, 5, true),
  ('neet-biology-chemical-co-ordination-and-integration-gh-disorders', 'neet-biology-chemical-co-ordination-and-integration', 'Growth Hormone Disorders', 'neet_trap', 'GH secretion level and timing produce different disorders.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["GH condition","Source-backed effect"],"rows":[["Over-secretion","Gigantism or abnormal growth"],["Hyposecretion","Dwarfism or stunted growth"],["Adult over-secretion","Acromegaly, severe disfigurement especially of face; serious complications and premature death"]]}'::jsonb, null, null, '{"recall_question":"Which GH disorder occurs due to adult over-secretion?","reveal_answer":"Acromegaly.","key_points":[],"examples":[],"neet_traps":["Hyposecretion causes dwarfism; over-secretion causes gigantism."]}'::jsonb, 5, 87, 6, true),
  ('neet-biology-chemical-co-ordination-and-integration-posterior-pituitary-hormones', 'neet-biology-chemical-co-ordination-and-integration', 'Oxytocin and ADH', 'comparison', 'Neurohypophysis stores oxytocin and vasopressin from hypothalamus.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Hormone","Source-backed function/disorder"],"rows":[["Oxytocin","Contracts smooth muscles; in females stimulates uterus contraction during childbirth and milk ejection"],["Vasopressin or ADH","Stimulates reabsorption of water and electrolytes by DCT of kidney and reduces diuresis"],["ADH deficiency","Diminished ability of kidney to conserve water, water loss and dehydration; Diabetes insipidus"]]}'::jsonb, null, null, '{"recall_question":"Which posterior pituitary hormone reduces diuresis?","reveal_answer":"Vasopressin or ADH.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 87, 7, true),
  ('neet-biology-chemical-co-ordination-and-integration-pineal-melatonin', 'neet-biology-chemical-co-ordination-and-integration', 'Pineal Gland and Melatonin', 'fact', 'Pineal is the smallest endocrine gland and is located on dorsal side of forebrain.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Cue","Source-backed detail"],"rows":[["Hormone","Melatonin"],["Rhythm","Regulates diurnal or 24-hour rhythm such as sleep-wake cycle and body temperature"],["Other effects","Influences metabolism, pigmentation, menstrual cycle and defense capability"]]}'::jsonb, null, null, '{"recall_question":"Which gland is the smallest endocrine gland in the source?","reveal_answer":"Pineal gland.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 4, 87, 8, true),
  ('neet-biology-chemical-co-ordination-and-integration-thyroid-hormones', 'neet-biology-chemical-co-ordination-and-integration', 'Thyroid Hormones', 'classification', 'The thyroid is the largest endocrine gland and contains follicles and stromal tissues.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Hormone","Source-backed function"],"rows":[["T4 and T3","Regulate basal metabolic rate"],["T4 and T3","Support physical, mental and sexual development"],["T4 and T3","Support RBC formation"],["T4 and T3","Control metabolism of carbohydrates, proteins and fats"],["T4 and T3","Maintain water and electrolyte balance"],["Thyrocalcitonin or TCT","Lowers blood calcium levels; hypocalcaemic hormone"]]}'::jsonb, null, null, '{"recall_question":"Which thyroid hormone lowers blood calcium level?","reveal_answer":"Thyrocalcitonin or TCT.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 88, 9, true),
  ('neet-biology-chemical-co-ordination-and-integration-thyroid-disorders', 'neet-biology-chemical-co-ordination-and-integration', 'Thyroid Disorders', 'comparison', 'The source connects iodine deficiency, thyroid hormone excess and specific symptoms.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Condition","Source-backed recall"],"rows":[["Goiter","Enlargement of thyroid gland due to deficiency of iodine"],["Hypothyroidism in adult women","Irregular menstrual cycle"],["Hypothyroidism during pregnancy","Stunted growth or cretinism, mental retardation, low intelligence quotient, abnormal skin, deaf-mutism etc."],["Hyperthyroidism","Abnormal increase of thyroid hormones with adverse physiological effects"],["Exophthalmic goiter or Grave''s disease","Hyperthyroidism with enlarged thyroid, protruded eyeballs, increased BMR and weight loss"]]}'::jsonb, null, null, '{"recall_question":"What causes goiter in the source?","reveal_answer":"Deficiency of iodine.","key_points":[],"examples":[],"neet_traps":["Grave''s disease is a form of hyperthyroidism."]}'::jsonb, 5, 88, 10, true),
  ('neet-biology-chemical-co-ordination-and-integration-parathyroid-pth', 'neet-biology-chemical-co-ordination-and-integration', 'Parathyroid Hormone', 'concept', 'Four parathyroid glands secrete parathyroid hormone or PTH, a peptide hormone.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Function","Source-backed detail"],"rows":[["Blood calcium","Increases Ca2+ level in blood; hypercalcaemic hormone"],["Bone","Stimulates bone resorption or demineralization"],["Kidney","Stimulates reabsorption of Ca2+ by renal tubules"],["Digestive food","Increases Ca2+ absorption from digested food"],["Balance","Along with TCT, helps calcium balance in the body"]]}'::jsonb, null, null, '{"recall_question":"Which hormone is hypercalcaemic in the source?","reveal_answer":"Parathyroid hormone (PTH).","key_points":[],"examples":[],"neet_traps":["TCT is hypocalcaemic."]}'::jsonb, 5, 88, 11, true),
  ('neet-biology-chemical-co-ordination-and-integration-thymus-thymosins', 'neet-biology-chemical-co-ordination-and-integration', 'Thymus and Thymosins', 'fact', 'Thymus is located between lungs behind sternum on the ventral side of aorta.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Cue","Source-backed detail"],"rows":[["Hormone","Thymosins, peptide hormones"],["Cell-mediated immunity","Differentiation of T-lymphocytes"],["Humoral immunity","Promote antibody production"],["Old age","Thymus degenerates, thymosin production decreases and immune responses weaken"]]}'::jsonb, null, null, '{"recall_question":"Which hormone promotes T-lymphocyte differentiation?","reveal_answer":"Thymosins.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 4, 88, 12, true),
  ('neet-biology-chemical-co-ordination-and-integration-adrenal-cortex-vs-medulla', 'neet-biology-chemical-co-ordination-and-integration', 'Adrenal Cortex vs Medulla', 'comparison', 'Adrenal gland has cortex and medulla with different hormone classes.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Feature","Adrenal cortex","Adrenal medulla"],"rows":[["Layers/part","Inner zona reticularis, middle zona fasciculata and outer zona glomerulosa","Medullary part"],["Hormones","Corticoid hormones","Catecholamines: adrenaline and noradrenaline"],["Main role","Metabolism, electrolyte/water balance and androgenic effects","Emergency hormones or fight-or-flight response"],["Disorder/effect","Deficiency causes Addison''s disease","Increases alertness, heartbeat and respiratory rate"]]}'::jsonb, null, null, '{"recall_question":"Which adrenal part secretes adrenaline and noradrenaline?","reveal_answer":"Adrenal medulla.","key_points":[],"examples":[],"neet_traps":["Adrenal cortex produces corticoid hormones."]}'::jsonb, 5, 88, 13, true),
  ('neet-biology-chemical-co-ordination-and-integration-adrenal-cortex-hormones', 'neet-biology-chemical-co-ordination-and-integration', 'Adrenal Cortex Hormones', 'table', 'The source separates adrenal cortex hormones into glucocorticoids, mineralocorticoids and androgenic corticoids.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Hormone group","Main source-backed functions"],"rows":[["Glucocorticoids mainly cortisol","Carbohydrate metabolism; stimulate gluconeogenesis, lipolysis and proteolysis; inhibit amino acid uptake; maintain cardiovascular and kidney functions; stimulate RBC production; anti-inflammatory and immune suppression"],["Mineralocorticoids mainly aldosterone","Regulate body fluid volume, electrolyte balance, osmotic pressure and blood pressure"],["Aldosterone","Stimulates reabsorption of Na+ and water from renal tubules and excretion of K+ and PO43- ions"],["Androgenic corticoids","Growth of axial hair, pubic hair and facial hair during puberty"]]}'::jsonb, null, null, '{"recall_question":"Which mineralocorticoid is named in the source?","reveal_answer":"Aldosterone.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 88, 14, true),
  ('neet-biology-chemical-co-ordination-and-integration-adrenal-medulla-hormones', 'neet-biology-chemical-co-ordination-and-integration', 'Adrenal Medulla Hormones', 'concept', 'Adrenaline and noradrenaline are catecholamines secreted rapidly in stress emergency situations.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Effect","Source-backed detail"],"rows":[["Name","Emergency hormones or hormones of fight or flight"],["Body effects","Increase alertness, pupillary dilation, piloerection, sweating, heartbeat, heart contraction and respiratory rate"],["Metabolic effects","Stimulate glycogenolysis to increase blood glucose; also stimulate lipolysis and proteolysis"]]}'::jsonb, null, null, '{"recall_question":"Which hormones are called fight-or-flight hormones in the source?","reveal_answer":"Adrenaline and noradrenaline.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 88, 15, true),
  ('neet-biology-chemical-co-ordination-and-integration-pancreas-islets', 'neet-biology-chemical-co-ordination-and-integration', 'Pancreas and Islets of Langerhans', 'fact', 'Pancreas is a composite or heterocrine gland: exocrine plus endocrine.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Cue","Source-backed detail"],"rows":[["Endocrine part","Islets of Langerhans"],["Islet number","About 1-2 million islets"],["Pancreatic tissue","1-2% of pancreatic tissue"],["Alpha cells","Secrete glucagon"],["Beta cells","Secrete insulin"],["Shared role","Maintain glucose homeostasis in blood"]]}'::jsonb, null, null, '{"recall_question":"Which pancreatic cells secrete insulin?","reveal_answer":"Beta cells.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 88, 16, true),
  ('neet-biology-chemical-co-ordination-and-integration-insulin-vs-glucagon', 'neet-biology-chemical-co-ordination-and-integration', 'Insulin vs Glucagon', 'comparison', 'Glucagon raises blood sugar; insulin lowers blood sugar.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Feature","Glucagon","Insulin"],"rows":[["Cell source","Alpha cells","Beta cells"],["Factor","Hyperglycemic factor","Hypoglycemic factor"],["Target cells","Hepatocytes","Hepatocytes and adipocytes"],["Main effect","Stimulates glycogenolysis and gluconeogenesis","Enhances cellular glucose uptake and utilization"],["Additional effect","Reduces cellular glucose uptake and utilization","Stimulates glycogenesis"]]}'::jsonb, '{"type":"bio-blood-glucose-regulation"}'::jsonb, null, '{"recall_question":"Which pancreatic hormone is hypoglycemic?","reveal_answer":"Insulin.","key_points":[],"examples":[],"neet_traps":["Glucagon is hyperglycemic."]}'::jsonb, 5, 88, 17, true),
  ('neet-biology-chemical-co-ordination-and-integration-diabetes-mellitus', 'neet-biology-chemical-co-ordination-and-integration', 'Diabetes Mellitus', 'neet_trap', 'Prolonged hyperglycemia leads to diabetes mellitus in the source.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Cue","Source-backed detail"],"rows":[["Cause phrase","Prolonged hyperglycemia"],["Effect","Loss of glucose through urine and formation of harmful compounds like ketone bodies"],["Treatment","Insulin therapy"]]}'::jsonb, null, null, '{"recall_question":"What treatment is stated for diabetes mellitus?","reveal_answer":"Insulin therapy.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 88, 18, true),
  ('neet-biology-chemical-co-ordination-and-integration-testis-androgens', 'neet-biology-chemical-co-ordination-and-integration', 'Testis and Androgens', 'concept', 'Leydig or interstitial cells in inter-tubular spaces produce androgens, mainly testosterone.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Function","Source-backed detail"],"rows":[["Accessory sex organs","Regulate development, maturation and functions"],["Spermatogenesis","Sperm production"],["Behaviour/characters","Stimulate sexual behavior, growth of muscles, hairs, aggressiveness, low pitch voice etc."],["Metabolism","Help in anabolism of protein and carbohydrate"]]}'::jsonb, null, null, '{"recall_question":"Which cells produce testosterone in the source?","reveal_answer":"Leydig or interstitial cells.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 89, 19, true),
  ('neet-biology-chemical-co-ordination-and-integration-estrogen-vs-progesterone', 'neet-biology-chemical-co-ordination-and-integration', 'Estrogen vs Progesterone', 'comparison', 'Ovarian follicles produce estrogen; corpus luteum secretes progesterone.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Feature","Estrogen","Progesterone"],"rows":[["Source","Ovarian follicles","Corpus luteum after ovulation"],["Hormone type","Steroid hormone","Steroid hormone"],["Functions","Growth and activities of female secondary sex organs; ovarian follicles and mammary glands; secondary sex characters and sexual behavior","Supports pregnancy; acts on mammary glands to form alveoli and milk secretion"]]}'::jsonb, null, null, '{"recall_question":"Which ovarian structure secretes progesterone?","reveal_answer":"Corpus luteum.","key_points":[],"examples":[],"neet_traps":["Ovarian follicles produce estrogen."]}'::jsonb, 5, 89, 20, true),
  ('neet-biology-chemical-co-ordination-and-integration-heart-kidney-gi-hormones', 'neet-biology-chemical-co-ordination-and-integration', 'Heart, Kidney and GI Hormones', 'table', 'The source includes hormones from heart, kidney and gastrointestinal tract.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Source","Hormone","Main function"],"rows":[["Atrial wall of heart","Atrial natriuretic factor (ANF)","When BP increases, dilates blood vessels to reduce BP"],["JGA of kidney","Erythropoietin","Stimulates erythropoiesis or formation of RBC"],["GI tract","Gastrin","Stimulates gastric glands to secrete HCl and pepsinogen"],["GI tract","Secretin","Stimulates exocrine pancreas to secrete water and bicarbonate ions"],["GI tract","Cholecystokinin (CCK)","Stimulates secretion of bile and pancreatic enzymes"],["GI tract","Gastric inhibitory peptide (GIP)","Inhibits gastric secretion"]]}'::jsonb, null, null, '{"recall_question":"Which kidney region produces erythropoietin in the source?","reveal_answer":"JGA of kidney.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 89, 21, true),
  ('neet-biology-chemical-co-ordination-and-integration-hormone-chemical-classes', 'neet-biology-chemical-co-ordination-and-integration', 'Chemical Classes of Hormones', 'classification', 'Hormones are classified by chemical nature.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Class","Source examples"],"rows":[["Peptide, polypeptide, protein hormones","Insulin, glucagon, pituitary hormones, hypothalamic hormones etc."],["Steroids","Cortisol, testosterone, estradiol and progesterone"],["Iodothyronines","Thyroid hormones"],["Amino-acid derivatives","Adrenaline, nor-adrenaline etc."]]}'::jsonb, null, null, '{"recall_question":"Which hormone class includes cortisol and testosterone?","reveal_answer":"Steroids.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 4, 89, 22, true),
  ('neet-biology-chemical-co-ordination-and-integration-hormone-receptors-overview', 'neet-biology-chemical-co-ordination-and-integration', 'Hormone Receptors', 'concept', 'Hormones act by binding specific receptor proteins in target tissues.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Step","Source-backed event"],"rows":[["1","Hormone binds a specific receptor"],["2","Hormone-receptor complex forms"],["3","Biochemical changes occur in target tissue"],["4","Metabolism and physiological functions are regulated"]]}'::jsonb, null, null, '{"recall_question":"What complex forms when a hormone binds its receptor?","reveal_answer":"Hormone-receptor complex.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 4, 89, 23, true),
  ('neet-biology-chemical-co-ordination-and-integration-membrane-vs-intracellular-receptors', 'neet-biology-chemical-co-ordination-and-integration', 'Membrane-Bound vs Intracellular Receptors', 'comparison', 'Hormone receptors are membrane-bound or intracellular.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Feature","Membrane-bound receptors","Intracellular receptors"],"rows":[["Hormone examples","Protein hormone, FSH","Steroid hormones, iodothyronines"],["Cell entry","Hormones do not enter target cell","Hormones interact with intracellular receptors"],["Messenger/action","Generate second messengers such as cyclic AMP, IP3 and Ca2+","Mostly regulate gene expression or chromosome function"],["Effect","Regulate cellular metabolism and physiological effects","Physiological and developmental effects"]]}'::jsonb, '{"type":"bio-hormone-receptor-types"}'::jsonb, null, '{"recall_question":"Which receptor type generates second messengers?","reveal_answer":"Membrane-bound receptors.","key_points":[],"examples":[],"neet_traps":["Steroid hormones and iodothyronines use intracellular receptors in the source."]}'::jsonb, 5, 89, 24, true)
